-- ===========================================================================
-- SIEMBRA DE LA BIBLIOTECA DE CONVOCATORIAS
--
-- Sale del archivo convocatorias_para_importar_v8.csv que ya tenías: 412 fichas
-- con su enlace o su entidad y su línea temática.
--
-- Honestidad de los datos: el CSV marcaba TODO como "Abierta", pero las que
-- tenían fecha fija cerraron en 2025. Aquí quedan con su fecha real y con el
-- estado "cerró el ...: verificar si abre otra edición", así que NO aparecen
-- como abiertas ni salen en la vista convocatorias_vigentes. Las de todo el
-- año quedan como permanentes, que es lo que de verdad son.
--
-- Se puede correr varias veces: si la ficha ya existe solo rellena huecos y
-- nunca pisa lo que haya escrito el equipo.
--
-- Requiere haber corrido antes supabase_migration_biblioteca.sql
-- ===========================================================================

ON CONFLICT (clave) DO UPDATE SET
  entidad             = COALESCE(NULLIF(public.biblioteca_convocatorias.entidad, ''), EXCLUDED.entidad),
  tipo                = COALESCE(public.biblioteca_convocatorias.tipo, EXCLUDED.tipo),
  estado_convocatoria = COALESCE(public.biblioteca_convocatorias.estado_convocatoria, EXCLUDED.estado_convocatoria),
  fecha_cierre        = COALESCE(public.biblioteca_convocatorias.fecha_cierre, EXCLUDED.fecha_cierre),
  monto               = COALESCE(public.biblioteca_convocatorias.monto, EXCLUDED.monto),
  linea_tematica      = COALESCE(public.biblioteca_convocatorias.linea_tematica, EXCLUDED.linea_tematica),
  fuente_oficial      = COALESCE(public.biblioteca_convocatorias.fuente_oficial, EXCLUDED.fuente_oficial),
  actualizado_en      = now();
